use serde_json::{json,Value};use sha2::{Digest,Sha256};use std::{fmt::Write,fs,path::{Path,PathBuf},process::Command};const R:&str="/home/ubuntu/src/zopro-perf-work/postgroup-phi176";const D:&str="/home/ubuntu/src/zk-tools/zopro/docs/benchmarks/2026-10-31-postgroup-phi176";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}fn walk(p:&Path,v:&mut Vec<PathBuf>){for e in fs::read_dir(p).unwrap(){let p=e.unwrap().path();if p.is_dir(){walk(&p,v)}else{v.push(p)}}}
fn main(){let r=Path::new(R);let d=Path::new(D);assert!(!d.join("artifacts/final-publication-review.json").exists());let a=read(r.join("analysis.json"));let review=read(r.join("review.json"));assert_eq!(a["gate_passed"],false);assert_eq!(review["passed"],true);let mut routes=vec![];for shape in["4x2","8x2","12x2","16x2","merge-24x1"]{let name=format!("preflight-{shape}-w32-ON");let item=review["route_snapshots"].as_array().unwrap().iter().find(|x|x["name"]==name).unwrap();let x=&item["counts"];routes.push(json!({"shape":shape,"original":x[3],"effective":x[4],"scalar_clone_requested_bytes":x[4].as_u64().unwrap()*32,"additional_typed_layout_reservation_bytes":x[5],"this_reservation_is_not_measured_heap_or_minimum_RAM":true}));}
 fs::write(r.join("actual-routes.json"),serde_json::to_vec_pretty(&routes).unwrap()).unwrap();fs::copy(r.join("actual-routes.json"),d.join("artifacts/actual-routes.json")).unwrap();
 let mut text=fs::read_to_string(d.join("README.md")).unwrap();fs::write(r.join("README-before-editorial.md"),&text).unwrap();let at=text.find("\n\n").unwrap()+2;text.insert_str(at,"Selecting Phi2 by the effective grouped size did not establish a full-proof speedup. The five-shape estimate is **0.08% slower than fresh OFF**, with bounds spanning parity, and **0.60% slower than accepted**, with bounds above parity. This rejects the fixed implementation without claiming every possible post-group dispatch must be slower.\n\n");text=text.replace("All observations remain, including calibration and memory failures.","All observations remain. All ten control calibrations and all maximum-RSS guards pass. The separate primary16 ON/accepted nonregression bound is 1.035058, above the declared 1.03; that is insufficient evidence for the guard, not an established 3.5% slowdown. The two aggregate gain failures independently prevent adoption.");
 let at=text.find("The SDK timing body").unwrap();let mut table=String::from("The actual admitted dimensions and requested scalar payloads follow. Additional layout reservation is conservative accounting over existing forecasts, not measured extra heap or minimum RAM. [Machine-readable dimensions](artifacts/actual-routes.json).\n\n|Shape|Original points|Effective terms|Scalar clone bytes|Additional typed reservation bytes|\n|---|---:|---:|---:|---:|\n");for v in &routes{writeln!(table,"|{}|{}|{}|{}|{}|",v["shape"].as_str().unwrap(),v["original"],v["effective"],v["scalar_clone_requested_bytes"],v["additional_typed_layout_reservation_bytes"]).unwrap();}table.push_str("\n");text.insert_str(at,&table);
 let at=text.find("Qualification retains").unwrap();text.insert_str(at,"The individual 4x2 estimate improves 0.950% versus OFF and 0.280% versus accepted, with 9/15 wins and both intervals spanning parity. The 16x2 OFF estimate improves 0.460%, also inconclusive. These positive estimates remain; no favorable shape is promoted independently. In the counter panels, 4x2 instructions rise from 2362.658M to 2389.767M/request and merge24 from 8739.486M to 8757.095M. This does not establish a reduction in overall arithmetic work or isolate a memory/scheduling cause.\n\n");
 text.push_str("\nA [preparation supplement](artifacts/preparation-supplement.tar.gz) retains the successful preparation log and total-count correction. Before any plan or capture, the job-sum assertion corrected 26,562 to 27,912 requests: the difference is 450 latency processes × three excluded primes. Timed request counts, blocks, contexts, thresholds and 498 exports never changed. One read-only preflight route check was added before timing. Original logs, helpers, source, successful captures and the failed native fixture remain in the archives. This editorial/closure step changes no source or performance data.\n");fs::write(d.join("README.md"),&text).unwrap();
 let files=["count-repair.md","capture-prepare-fixed.log","capture-prepare.log","seal-ready.log","repair-fixture.log","actual-routes.json","finalize-report.rs","README-before-editorial.md"];
 let archive=d.join("artifacts/preparation-supplement.tar.gz");assert!(Command::new("tar").args(["--sort=name","--mtime=@0","--owner=0","--group=0","--numeric-owner","-czf"]).arg(&archive).arg("-C").arg(R).args(files).status().unwrap().success());let out=r.join("supplement-review");fs::create_dir(&out).unwrap();assert!(Command::new("tar").arg("-xzf").arg(&archive).arg("-C").arg(&out).status().unwrap().success());for file in files{assert_eq!(hash(out.join(file)),hash(r.join(file)));}
 let mut counts=serde_json::Map::new();for group in["source","workflow","receipts","proofs","codegen"]{let base=r.join("archive-review").join(group);let mut files=vec![];walk(&base,&mut files);for file in &files{assert_eq!(hash(file),hash(r.join(file.strip_prefix(&base).unwrap())));}counts.insert(group.into(),json!(files.len()));}counts.insert("preparation-supplement".into(),json!(8));
 let mut links=0;for x in text.split("](").skip(1){let p=x.split(')').next().unwrap();if !p.starts_with("http"){assert!(d.join(p).is_file());}links+=1;}let v=json!({"passed":true,"archive_member_sets_byte_exact":counts,"report_links_checked":links,"report_sha256":hash(d.join("README.md")),"raw_analysis_sha256":hash(r.join("analysis.json")),"raw_review_sha256":hash(r.join("review.json")),"all_control_calibration_and_RSS_guards_pass":true,"full_performance_gate_false":true,"ledger":27851,"new_verified_exports":498,"production_adopted":false,"editorial_only_after_first_publisher":true});fs::write(d.join("artifacts/final-publication-review.json"),serde_json::to_vec_pretty(&v).unwrap()).unwrap();fs::copy(r.join("finalize-report.rs"),d.join("artifacts/finalize-report.rs")).unwrap();let mut files=vec![];walk(d,&mut files);files.sort();let mut sums=String::new();for p in files{if p.file_name().unwrap()=="SHA256SUMS"{continue}writeln!(sums,"{}  {}",hash(&p),p.strip_prefix(d).unwrap().display()).unwrap();}fs::write(d.join("SHA256SUMS"),sums).unwrap();println!("{v}");}
